#!/usr/bin/env python3
import csv, collections
phases = collections.OrderedDict()
for row in csv.DictReader(open("incident_timeline.csv")):
    phases.setdefault(row["phase"], []).append(row["event"])
print("NIST SP 800-61 incident report")
for ph, evs in phases.items():
    print("[%s] %d event(s)" % (ph, len(evs)))
print("post-incident action item: nto{n1st_800_61_p0st_1nc1d3nt}")
